/* hls_top.c — the control as the top function of an FPGA IP (AMD/Xilinx Vitis HLS), generated by MaiSim.
   HLS reads this C (the same as in the SIL) and generates the VHDL/Verilog: on each call (every Ts), the measurements come in on m
   and the actuations go out on u; the state stays in registers (static). In floating point (float) it is direct; for fixed point,
   build as C++ with typedef ap_fixed<W,I> maisim_real and the hls_math functions (see LEIA.md).
   Measurement order: {{ORDEM_M}}; of the actuations: {{ORDEM_U}}. */
#include "maisim_controle.h"
#include "maisim_parametros.h"

void maisim_top(const maisim_real m[MAISIM_N_M], maisim_real u[MAISIM_N_U]) {
#pragma HLS INTERFACE s_axilite port=return
#pragma HLS INTERFACE s_axilite port=m
#pragma HLS INTERFACE s_axilite port=u
    static long long estado[1 << 10];
    static maisim_real p[MAISIM_N_P];
    static unsigned long n;            /* t = n·Ts */
    static int iniciado = 0;
    int k;
    if (!iniciado) {
        for (k = 0; k < MAISIM_N_P; k++) p[k] = maisim_p_iniciais[k];
        maisim_iniciar(p, estado);
        n = 0;
        iniciado = 1;
    }
    maisim_passo((maisim_real)((double)n * MAISIM_TS), m, p, estado, u);
    n++;
}
